    return any(
        原理.対象系境界 == 境界
        and 原理.関係型 == "同値関係"
        and 原理.条件経路群 == (("候補",),)
        and 原理.結果経路 == ("出力",)
        for 原理 in 原理群
    )


def 出力格子(機械, 観測, *, 同値必須=False):
    実行結果 = 機械.照会(観測)
    排気 = 最小排気系().排出する(実行結果)
    値群 = [p.予測値 for p in 実行結果.予測群 if p.結果経路 == ("出力",)]
    同値あり = 同値原理あり(実行結果.有効原理群, 観測.対象系境界)
    確定 = (
        排気.状態 == "出力" and bool(値群)
        and all(v == 値群[0] for v in 値群)
        and 有効格子(値群[0]) and (not 同値必須 or 同値あり)
    )
    return {
        "answer": 値群[0] if 確定 else None,
        "status": 排気.状態, "reasons": 排気.内容["断定保留理由群"],
        "equality_admitted": 同値あり,
        "quarantined": len(実行結果.係争中原理群),
    }","ref":"d21ecb838bcf77dfc9e7f045ac066000657e2723","source_kind":"pinned_code","source_path":"接続/ARC2/HDS接続.py"},{"blob_sha":"7f14455fc147d89d8a16b2aba588ea13b8f9f406","caveat":"この記述はadapterの条件分岐。HDS中核の隔離・保留理由の全内部分岐や実際の学習/排出結果を再現したものではない。予測群なしでは基底結果を返すので、この分岐単独で常にstatus='断定保留'と定数化しない。","claim_ja":"共有HDS gate（局所候補Noneとは別）: 基底だけで全testのanswerが得られた場合は機構学習前に早期return。機構照会経路では全機構学習後、採用可かつ同値採用の機構だけを照会する。そのいずれかがtest候補None又はHDS排気保留なら、他機構に答えがあっても断定保留。未解決理由がなく、得た完全格子予測が全て一致したときだけ採用し、異なれば断定保留。各HDS出力は排気状態『出力』、予測非空・相互同値、有効ARC格子、同値必須時は候補→出力同値原理を要求する。","evidence_kind":"現行固定コードの契約（実行結果ではない）","line_end":188,"line_start":179,"quote":"    二例 = (len(課題["train"]) == 2
            and 課題["train"][0]["input"] != 課題["train"][1]["input"])
    必要支持数 = 2 if 二例 else 3
    # 課題全体に作用する明示設定。HDS中核の既定値3は変更しない。
    機械 = HDS学習実行系(最小支持数=必要支持数)
    for 対 in 課題["train"]:
        機械.実行(格子観測(対))
    基底 = [出力格子(機械, 格子観測(対)) for 対 in 課題["test"]]
    if all(結果["answer"] is not None for 結果 in 基底):
        return {"results": 基底, "mechanism": "格子値基底", "minimum_support": 必要支持数}","ref":"d21ecb838bcf77dfc9e7f045ac066000657e2723","source_kind":"pinned_code","source_path":"接続/ARC2/HDS接続.py"},{"blob_sha":"7f14455fc147d89d8a16b2aba588ea13b8f9f406","caveat":"この記述はadapterの条件分岐。HDS中核の隔離・保留理由の全内部分岐や実際の学習/排出結果を再現したものではない。予測群なしでは基底結果を返すので、この分岐単独で常にstatus='断定保留'と定数化しない。","claim_ja":"共有HDS gate（局所候補Noneとは別）: 基底だけで全testのanswerが得られた場合は機構学習前に早期return。機構照会経路では全機構学習後、採用可かつ同値採用の機構だけを照会する。そのいずれかがtest候補None又はHDS排気保留なら、他機構に答えがあっても断定保留。未解決理由がなく、得た完全格子予測が全て一致したときだけ採用し、異なれば断定保留。各HDS出力は排気状態『出力』、予測非空・相互同値、有効ARC格子、同値必須時は候補→出力同値原理を要求する。","evidence_kind":"現行固定コードの契約（実行結果ではない）","line_end":355,"line_start":324,"quote":"    記録群 = [候補機構を学習(機械, 課題, 教材, 境界, 候補器)
              for 境界, 候補器, 教材 in 機構群]
    結果群 = []
    隔離数 = 0
    for 対 in 課題["test"]:
        # 全機構の学習後に照会するため、後発の隔離も既存排気gateへ反映される。
        基底結果 = 出力格子(機械, 格子観測(対))
        隔離数 = max(隔離数, 基底結果["quarantined"])
        予測群 = [] if 基底結果["answer"] is None else [基底結果]
        未解決理由 = []
        for (境界, 候補器, _), 記録 in zip(機構群, 記録群):
            if not 記録["採用可"] or not 記録["同値採用"]:
                continue
            候補, _ = 候補器(対["input"], {})
            if 候補 is None:
                未解決理由.append(f"採用済み機構{境界}のtest候補が未確定")
                continue
            予測 = 出力格子(機械, 観測へ({"候補": 候補}, 境界), 同値必須=True)
            if 予測["answer"] is not None:
                予測群.append({**予測, "family": 境界})
            else:
                未解決理由.append(f"採用済み機構{境界}のHDS排気が保留")
        if 未解決理由:
            結果群.append({"answer": None, "status": "断定保留", "reasons": 未解決理由})
        elif not 予測群:
            結果群.append(基底結果)
        elif all(p["answer"] == 予測群[0]["answer"] for p in 予測群):
            結果群.append({**予測群[0], "agreeing_predictions": len(予測群)})
        else:
