    remaining = set(cells)
    component_count = 0
    while remaining:
        component_count += 1
        stack = [remaining.pop()]
        while stack:
            row, col = stack.pop()
            for neighbor in (
                (row - 1, col),
                (row + 1, col),
                (row, col - 1),
                (row, col + 1),
            ):
                if neighbor in remaining:
                    remaining.remove(neighbor)
                    stack.append(neighbor)
    return component_count

def _nested_panel_relation_record(
    grid: Grid,
    row: int,
    col: int,
    size: int,
    marker_color: int,
    background: int,
) -> dict[str, Any] | None:
    height, width = _grid_shape(grid)
    if size < 3 or row + size > height or col + size > width:
        return None
    base = int(grid[row][col])
    if base == background:
        return None
    if any(
        grid[row][current_col] != base
        or grid[row + size - 1][current_col] != base
        for current_col in range(col, col + size)
    ):
        return None
    if any(
        grid[current_row][col] != base
        or grid[current_row][col + size - 1] != base
        for current_row in range(row, row + size)
    ):
        return None
    non_base_cells = {
        (current_row, current_col)
        for current_row in range(row + 1, row + size - 1)
        for current_col in range(col + 1, col + size - 1)
        if grid[current_row][current_col] != base
    }
    if non_base_cells and {
        int(grid[current_row][current_col])
        for current_row, current_col in non_base_cells
    } != {marker_color}:
        return None
    marker_cells = {
        (current_row, current_col)
        for current_row, current_col in non_base_cells
        if int(grid[current_row][current_col]) == marker_color
    }
    return {
        "row": row,
        "col": col,
        "size": size,
        "base": base,
        "marker_component_count": _orthogonal_component_count(marker_cells),
        "marker_cell_count": len(marker_cells),
        "cells": {
            (current_row, current_col)
            for current_row in range(row, row + size)
            for current_col in range(col, col + size)
        },
    }","ref":"d21ecb838bcf77dfc9e7f045ac066000657e2723","source_kind":"pinned_code","source_path":"接続/ARC2/既存入れ子合成.py"},{"blob_sha":"784e84e051767564075e2abc9b85879d0e811ad1","caveat":"固定コードの分岐から読める契約。実行結果、教師経験、一般化性能の主張ではない。","claim_ja":"正方形一様枠、単一marker、target/sourceの辺長差2、markerの4近傍成分数一致、2枚以上の極大target layout、target/source各base相異、非重複、source markerをtarget baseへ変換する描画が固定文法。rendererはraw候補数が厳密に1のときだけ出す。","evidence_kind":"現行固定コードの契約（実行結果ではない）","line_end":137,"line_start":84,"quote":"def _nested_panel_layout(
