def full_separator_lines(grid: Grid) -> dict[int, dict[str, list[int]]]:
    if not is_rectangular(grid):
        return {}
    height, width = grid_shape(grid)
    result: dict[int, dict[str, list[int]]] = {}
    for color in sorted({value for row in grid for value in row}):
        rows = [row for row in range(height) if all(value == color for value in grid[row])]
        cols = [
            col
            for col in range(width)
            if all(grid[row][col] == color for row in range(height))
        ]
        if rows or cols:
            result[color] = {"rows": rows, "cols": cols}
    return result

def framed_panel_bboxes(grid: Grid) -> list[tuple[int, int, int, int, int | None]]:
    if not is_rectangular(grid):
        return []
    height, width = grid_shape(grid)
    bboxes: list[tuple[int, int, int, int, int | None]] = []

    for color, lines in full_separator_lines(grid).items():
        rows = lines["rows"]
        cols = lines["cols"]
        if not (0 in rows and height - 1 in rows and 0 in cols and width - 1 in cols):
            continue
        for row_index in range(len(rows) - 1):
            top = rows[row_index]
            bottom = rows[row_index + 1]
            if bottom - top < 2:
                continue
            for col_index in range(len(cols) - 1):
                left = cols[col_index]
                right = cols[col_index + 1]
                if right - left < 2:
                    continue
                bboxes.append((top, left, bottom, right, color))

    return bboxes or [(0, 0, height - 1, width - 1, None)]

def peel_uniform_borders(
    grid: Grid, bbox: tuple[int, int, int, int, int | None]
) -> tuple[int, int, int, int, list[int]]:
    top, left, bottom, right, _ = bbox
    peeled_colors: list[int] = []
    while bottom - top >= 2 and right - left >= 2:
        perimeter = (
            [grid[top][col] for col in range(left, right + 1)]
            + [grid[bottom][col] for col in range(left, right + 1)]
            + [grid[row][left] for row in range(top, bottom + 1)]
            + [grid[row][right] for row in range(top, bottom + 1)]
        )
        colors = set(perimeter)
        if len(colors) != 1:
            break
        peeled_colors.append(next(iter(colors)))
        top += 1
        left += 1
        bottom -= 1
        right -= 1
    return top, left, bottom, right, peeled_colors

def certify_sequence(sequence):
    if not sequence:
        return None,{'failure':'empty_sequence'}
    choices=[]
    for period in range(1,min(6,len(sequence))+1):
        tuple_cost=0
        cell_cost=0
        modal_choices=[]
        for offset in range(period):
            values=sequence[offset::period]
            counts=Counter(values)
            maximum=max(counts.values())
            modes=[v for v,n in counts.items()if n==maximum]
            costs={v:sum(sequence_cell_mismatch(v,x)for x in values)for v in modes}
            best_cell=min(costs.values())
            modal_choices.append([v for v in modes if costs[v]==best_cell])
            tuple_cost+=len(values)-maximum
            cell_cost+=best_cell
        choices.append({'score':(tuple_cost,cell_cost,period),'modes':modal_choices})
    best=min(choices,key=lambda x:x['score'])
    if any(len(v)!=1 for v in best['modes']):
        return None,{'failure':'tied_optimal_modal_tuples','score':best['score']}
    motif=[v[0]for v in best['modes']]
    candidate=[motif[i%len(motif)]for i in range(len(sequence))]
    raw,record=repair_tuple_sequence(sequence)
    raw_score=(record['tuple_mismatch'],record['cell_mismatch'],record['period'])
    if raw!=candidate or raw_score!=best['score']:
        return None,{'failure':'source_choice_not_unique_optimum','score':best['score'],'source_score':raw_score}
    if best['score'][0]>max(1,len(sequence)//3):
        return None,{'failure':'panel_exceeds_original_noise_budget','score':best['score']}
    return raw,{'score':best['score']}

