                return None, {'failure': 'source_axis_disagrees', 'color': color}
            for r, c in removed:
                expected[r][c] = background
            certificates.append({'color': color, 'component_size': len(cells), 'axis2': axis2,
                                 'kept_count': len(kept), 'removed_count': len(removed),
                                 'original_removal_limit': limit})
    output, record = apply_vertical_symmetry_pruning(grid)
    if output is None:
        return None, record or {'failure': 'source_no_candidate'}
    if output != expected:
        return None, {'failure': 'source_output_disagrees'}
    return output, {**record, 'maximum_retention_certificate': certificates}


class 対称剪定教材:
    def __init__(self, 教師群):
        self.全教師再現 = False
        if not 教師群 or len({tuple(map(tuple, p['input'])) for p in 教師群}) != len(教師群):
            return
        self.全教師再現 = all(guarded_render(p['input'])[0] == p['output'] for p in 教師群)

    def 候補(self, 格子, _policy):
        if not self.全教師再現:
            return None, {'failure': '全教師を再現する最大保持対称剪定なし'}
        return guarded_render(格子)

    def 記録(self):
        return {'全教師再現': self.全教師再現}

def apply_vertical_symmetry_pruning(grid: Grid) -> tuple[Grid | None, dict | None]:
    background = dominant_color(grid)
    output = clone_grid(grid)
    actions = []
    for color in sorted({value for row in grid for value in row if value != background}):
        for cells in same_color_components_8(grid, color):
            if len(cells) < 2:
                continue
            candidate = vertical_prune_candidate(cells)
            if candidate is None:
                continue
            max_removed = max(3, len(cells) // MAX_REMOVAL_FRACTION_DIVISOR + 1)
            if len(candidate["removed"]) > max_removed:
                continue
            removed = sorted(candidate["removed"])
            for row, col in removed:
                output[row][col] = background
            actions.append(
                {
                    "color": color,
                    "component_bbox": bbox(cells),
                    "component_size": len(cells),
                    "axis2": candidate["axis2"],
                    "removed_cells": removed,
                    "removed_count": len(removed),
                    "kept_count": len(candidate["kept"]),
                    "kept_bbox": bbox(candidate["kept"]),
                    "kept_height": candidate["kept_height"],
                    "kept_width": candidate["kept_width"],
                }
            )

    if not actions:
        return None, None
    return output, {
        "background": background,
        "actions": actions,
        "action_count": len(actions),
        "changed_count": sum(action["removed_count"] for action in actions),
    }

def 有効格子(格子):
    return (
