                    if not (0 <= next_row < height and 0 <= next_col < width):
                        continue
                    if next_cell in seen or int(key[next_row][next_col]) == int(background_color):
                        continue
                    seen.add(next_cell)
                    queue.append(next_cell)
            records.append(_region_feature_record(cells, color_counts))

