                continue
            queue = [cell]
            seen.add(cell)
            cells: list[tuple[int, int]] = []
            touches_bbox = False
            for current_row, current_col in queue:
                cells.append((current_row, current_col))
                touches_bbox = touches_bbox or current_row in (0, height - 1) or current_col in (0, width - 1)
