    cells: list[tuple[int, int]],
    shape: tuple[int, int],
) -> tuple[float, float]:
    height, width = shape
    return (
        sum(row for row, _ in cells) / len(cells) / height,
        sum(col for _, col in cells) / len(cells) / width,
    )

